import{_ as n,o as t,c as e,a2 as i}from"./chunks/framework.2Es64uX1.js";const l=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"Kỹ Thuật Phần Mềm Ứng Dụng","tagline":"Architecture, Clean Code, Enterprise Design Patterns & Modern DevSecOps","actions":[{"theme":"brand","text":"🚀 Bắt đầu đọc Bài giảng","link":"/ch00_loi_noi_dau"},{"theme":"alt","text":"📋 Đề cương chi tiết (Syllabus)","link":"/syllabus"}]},"features":[{"icon":"🏗️","title":"Kiến Trúc & Thiết Kế Phần Mềm Chuẩn Mực","details":"Từ mô hình hóa C4 Model (Context, Container, Component), Clean Architecture, Domain-Driven Design (DDD) đến vi dịch vụ (Microservices) và Event-Driven Architecture (EDA Saga)."},{"icon":"🩺","title":"Case Study Thực Chiến Dr May Day v2.0","details":"Hệ sinh thái Y tế số thông minh đồng hành xuyên suốt 13 chương, tích hợp kho mã nguồn Docker Compose mẫu sẵn sàng chạy trên môi trường thực tế."},{"icon":"⚡","title":"Văn Hóa DevSecOps & Tự Động Hóa","details":"Luồng CI/CD hoàn chỉnh, kiểm thử tự động (TDD/BDD), an toàn bảo mật Shift-Left (SAST/DAST/SCA) và hệ thống quan sát OpenTelemetry (Logs, Metrics, Traces)."},{"icon":"🤖","title":"AI-Augmented SE & MLOps Tiên Tiến","details":"Kỹ thuật phần mềm tăng cường trợ lý AI/LLM, đặc tả prompt kỹ thuật, vận hành mô hình máy học (MLOps) và kiến trúc đa nền tảng hiện đại (Microfrontends)."}]},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),s={name:"index.md"};function h(c,a,p,r,o,d){return t(),e("div",null,[...a[0]||(a[0]=[i('<h2 id="📚-danh-muc-13-chuong-bai-giang" tabindex="-1">📚 Danh Mục 13 Chương Bài Giảng <a class="header-anchor" href="#📚-danh-muc-13-chuong-bai-giang" aria-label="Permalink to &quot;📚 Danh Mục 13 Chương Bài Giảng&quot;">​</a></h2><div class="chapter-grid"><a href="/ktpmud-book/ch00_loi_noi_dau" class="chapter-card"><div><span class="badge-archetype badge-intro">Case Study Hub</span><span style="font-size:0.8rem;color:var(--vp-c-text-3);">Chương 00</span></div><h3>Chương 0: Lời Nói Đầu &amp; Định Vị Case Study Xuyên Suốt</h3><p>Chuyển dịch từ Lập trình sang Kỹ thuật phần mềm qua thời gian, 5 nhóm năng lực cốt lõi và giới thiệu Hệ sinh thái Dr May Day v2.0.</p><div class="meta"><span>🩺 Dr May Day v2.0 &amp; C4 Level 1-2</span></div></a><a href="/ktpmud-book/ch01_tong_quan_sdlc" class="chapter-card"><div><span class="badge-archetype badge-found">Nền tảng</span><span style="font-size:0.8rem;color:var(--vp-c-text-3);">Chương 01</span></div><h3>Chương 1: Tổng Quan KTPM Ứng Dụng &amp; Các Mô Hình SDLC</h3><p>Bản chất kỹ thuật phần mềm, các mô hình quy trình cổ điển (Waterfall, V-Model, Spiral) và chuyển dịch sang Agile hiện đại.</p><div class="meta"><span>🔄 SDLC &amp; Process Models</span></div></a><a href="/ktpmud-book/ch02_yeu_cau_thiet_ke_c4" class="chapter-card"><div><span class="badge-archetype badge-arch">Kiến trúc</span><span style="font-size:0.8rem;color:var(--vp-c-text-3);">Chương 02</span></div><h3>Chương 2: Kỹ Thuật Yêu Cầu &amp; Thiết Kế Hệ Thống C4 Model</h3><p>Thu thập yêu cầu chức năng / phi chức năng, User Stories &amp; BDD, kiến trúc 4 tầng C4 Model trực quan hóa hệ thống lớn.</p><div class="meta"><span>📐 C4 Model &amp; Requirements</span></div></a><a href="/ktpmud-book/ch03_oop_clean_code" class="chapter-card"><div><span class="badge-archetype badge-code">Mã nguồn sạch</span><span style="font-size:0.8rem;color:var(--vp-c-text-3);">Chương 03</span></div><h3>Chương 3: Thiết Kế Hướng Đối Tượng &amp; Clean Code</h3><p>4 trụ cột OOP, bộ nguyên lý SOLID thực chiến, kỹ thuật Refactoring loại bỏ Code Smells và nâng cao tính bảo trì phần mềm.</p><div class="meta"><span>🧼 SOLID Principles &amp; Refactoring</span></div></a><a href="/ktpmud-book/ch04_design_patterns_thuc_chien" class="chapter-card"><div><span class="badge-archetype badge-code">Mẫu thiết kế</span><span style="font-size:0.8rem;color:var(--vp-c-text-3);">Chương 04</span></div><h3>Chương 4: Mẫu Thiết Kế Thực Chiến Trong Doanh Nghiệp</h3><p>Bộ 23 Gang of Four (GoF) patterns, Factory, Singleton, Strategy, Observer, Decorator và ứng dụng trong dự án thực tế.</p><div class="meta"><span>🧩 GoF Enterprise Design Patterns</span></div></a><a href="/ktpmud-book/ch05_agile_devsecops" class="chapter-card"><div><span class="badge-archetype badge-ops">Agile &amp; DevOps</span><span style="font-size:0.8rem;color:var(--vp-c-text-3);">Chương 05</span></div><h3>Chương 5: Quản Lý Dự Án Agile &amp; Văn Hóa DevSecOps</h3><p>Scrum nâng cao, Kanban, chiến lược phân nhánh Git Flow &amp; Trunk-Based, văn hóa an toàn bảo mật dịch chuyển sang trái (Shift-Left).</p><div class="meta"><span>🛡️ Scrum, Git Flow &amp; DevSecOps</span></div></a><a href="/ktpmud-book/ch06_kien_truc_microservices_eda" class="chapter-card"><div><span class="badge-archetype badge-arch">Kiến trúc</span><span style="font-size:0.8rem;color:var(--vp-c-text-3);">Chương 06</span></div><h3>Chương 6: Kiến Trúc Microservices &amp; Event-Driven (EDA)</h3><p>Chuyển đổi Monolith qua Strangler Fig pattern, thiết kế vi dịch vụ phân tán, mẫu điều phối Saga và hàng đợi thông điệp Kafka/RabbitMQ.</p><div class="meta"><span>⚡ Microservices, Saga &amp; Kafka</span></div></a><a href="/ktpmud-book/ch07_kiem_thu_tu_dong_cicd" class="chapter-card"><div><span class="badge-archetype badge-ops">Kiểm thử</span><span style="font-size:0.8rem;color:var(--vp-c-text-3);">Chương 07</span></div><h3>Chương 7: Kiểm Thử Tự Động &amp; Luồng CI/CD Toàn Diện</h3><p>Kim tự tháp kiểm thử (Unit, Integration, E2E), Mocking &amp; Test Doubles, xây dựng Pipeline GitHub Actions tự động kiểm định chất lượng.</p><div class="meta"><span>🧪 Automated Testing &amp; CI/CD</span></div></a><a href="/ktpmud-book/ch08_api_du_lieu_lon" class="chapter-card"><div><span class="badge-archetype badge-data">API &amp; Dữ liệu</span><span style="font-size:0.8rem;color:var(--vp-c-text-3);">Chương 08</span></div><h3>Chương 8: Thiết Kế API &amp; Quản Trị Dữ Liệu Quy Mô Lớn</h3><p>Chuẩn RESTful, GraphQL, gRPC hiệu năng cao, chiến lược Caching (Redis), phân mảnh Sharding, Replication và tính nhất quán BASE/ACID.</p><div class="meta"><span>🌐 REST, gRPC, Redis &amp; Big Data</span></div></a><a href="/ktpmud-book/ch09_ai_augmented_se_llm" class="chapter-card"><div><span class="badge-archetype badge-ai">AI &amp; LLM</span><span style="font-size:0.8rem;color:var(--vp-c-text-3);">Chương 09</span></div><h3>Chương 9: KTPM Tăng Cường Trí Tuệ Nhân Tạo &amp; LLM</h3><p>Tương tác trợ lý lập trình tạo sinh (Copilot/Gemini), Prompt Engineering cho kiểm thử/tái cấu trúc và kiểm soát rủi ro an ninh sinh mã.</p><div class="meta"><span>🤖 Generative AI &amp; Copilot Assist</span></div></a><a href="/ktpmud-book/ch10_mlops_tich_hop_ai" class="chapter-card"><div><span class="badge-archetype badge-ai">MLOps</span><span style="font-size:0.8rem;color:var(--vp-c-text-3);">Chương 10</span></div><h3>Chương 10: Vận Hành Mô Hình Máy Học &amp; MLOps Thực Chiến</h3><p>Đóng gói mô hình trí tuệ nhân tạo, Pipeline dữ liệu huấn luyện, kiểm soát lệch phân phối (Data Drift) và triển khai suy luận độ trễ thấp.</p><div class="meta"><span>📈 Model Serving &amp; Drift Monitoring</span></div></a><a href="/ktpmud-book/ch11_bao_mat_observability" class="chapter-card"><div><span class="badge-archetype badge-ops">Bảo mật</span><span style="font-size:0.8rem;color:var(--vp-c-text-3);">Chương 11</span></div><h3>Chương 11: Bảo Mật Ứng Dụng, Tối Ưu &amp; Observability</h3><p>Khung bảo mật OWASP Top 10, xác thực OAuth2 / JWT, mã hóa dữ liệu y sinh, tối ưu hóa độ trễ và giám sát 3 trụ cột OpenTelemetry.</p><div class="meta"><span>🔒 OWASP, OAuth2 &amp; OpenTelemetry</span></div></a><a href="/ktpmud-book/ch12_microfrontends_crossplatform" class="chapter-card"><div><span class="badge-archetype badge-code">Giao diện</span><span style="font-size:0.8rem;color:var(--vp-c-text-3);">Chương 12</span></div><h3>Chương 12: Kiến Trúc Vi Giao Diện &amp; Đa Nền Tảng</h3><p>Kiến trúc Microfrontends (Module Federation), tối ưu hóa trải nghiệm người dùng Web/Mobile, Progressive Web Apps (PWA) và React Native/Flutter.</p><div class="meta"><span>📱 Microfrontends, PWA &amp; Mobile</span></div></a></div>',2)])])}const m=n(s,[["render",h]]);export{l as __pageData,m as default};
